import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { auth } from "@/auth";
import { getProduct, fetchProducts } from "@/lib/products";

type EditProductPageProps = {
  params: Promise<{ id: string }>;
};

export default async function EditProductPage({
  params,
}: EditProductPageProps) {
  // ตรวจสอบว่า Login แล้วหรือยัง
  const session = await auth();

  if (!session?.user) {
    redirect("/");
  }

  const { id } = await params;

  // ลองหาสินค้าที่เพิ่มเองก่อน
  let product = getProduct(id);

  // ถ้าไม่มี ให้ลองหาจาก DummyJSON
  if (!product) {
    const result = await fetchProducts({
      q: "",
      limit: 100,
      sortBy: "title",
    });

    product = result.products.find(
      (item) => item.id === id,
    );
  }

  // ถ้าหาสินค้าไม่เจอจริง ๆ ค่อย 404
  if (!product) {
    notFound();
  }

  return (
    <main
      style={{
        padding: "40px",
        maxWidth: "700px",
        margin: "0 auto",
      }}
    >
      <h1>แก้ไขสินค้า</h1>

      <form
        style={{
          display: "grid",
          gap: "16px",
          marginTop: "24px",
        }}
      >
        <div>
          <label>ชื่อสินค้า</label>

          <input
            type="text"
            defaultValue={product.title}
            style={{
              display: "block",
              width: "100%",
              padding: "10px",
              marginTop: "6px",
            }}
          />
        </div>

        <div>
          <label>ราคา</label>

          <input
            type="number"
            defaultValue={product.price}
            style={{
              display: "block",
              width: "100%",
              padding: "10px",
              marginTop: "6px",
            }}
          />
        </div>

        <div>
          <label>รายละเอียด</label>

          <textarea
            defaultValue={product.description}
            rows={5}
            style={{
              display: "block",
              width: "100%",
              padding: "10px",
              marginTop: "6px",
            }}
          />
        </div>

        <div
          style={{
            display: "flex",
            gap: "10px",
          }}
        >
          <button type="submit">
            บันทึก
          </button>

          <Link href="/">
            กลับหน้าหลัก
          </Link>
        </div>
      </form>
    </main>
  );
}